function countSymmetricIntegers(low, high) {
  let count = 0;
  for (let x = low; x <= high; x++) {
    const digits = String(x);
    if (digits.length % 2 === 1) {
      continue;
    }
    const half = digits.length / 2;
    let balance = 0;
    for (let i = 0; i < half; i++) {
      balance += Number(digits[i]) - Number(digits[i + half]);
    }
    if (balance === 0) {
      count++;
    }
  }
  return count;
}

