function countSymmetricIntegers(low, high) {
  // Build every symmetric number with 2 or 4 digits from its digits, then keep those in range.
  let count = 0;
  const inRange = v => v >= low && v <= high;
  for (let a = 1; a <= 9; a++) if (inRange(11 * a)) count++;
  for (let a = 1; a <= 9; a++)
    for (let b = 0; b <= 9; b++)
      for (let c = 0; c <= 9; c++)
        for (let d = 0; d <= 9; d++)
          if (a + b === c + d && inRange(1000 * a + 100 * b + 10 * c + d)) count++;
  return count;
}

