function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  if (size === 'large') {
    const low = int(1, 100);
    return [low, int(9000, 10000)];
  }
  const pick = rand();
  if (pick < 0.3) {
    const low = int(1, 120);
    return [low, Math.min(10000, low + int(0, 30))];
  }
  if (pick < 0.6) {
    const low = int(990, 9990);
    return [low, Math.min(10000, low + int(0, 60))];
  }
  const a = int(1, 10000), b = int(1, 10000);
  return [Math.min(a, b), Math.max(a, b)];
}
